    save(out,'TEST_SPLIT_ELIGIBILITY_V2.json',testdata)
    invalid=collections.Counter(r.get('full_reason') or 'no contradiction' for r in rec.values() if r['full_status']!='VERIFIED');extra={s:[r for r in rec.values() if r['split']==s and r['additional_e012']] for s in ['train','validation']}
